  const ring = (cx, cy, r, n) => Array.from({ length: n }, (_, i) => [+(cx + r * Math.cos(2 * Math.PI * i / n)).toFixed(4), +(cy + r * Math.sin(2 * Math.PI * i / n)).toFixed(4)]);
